import React from 'react';
import { thStyle, tdStyle, groupThStyle } from './table-cell-styles.js';

/* `truncate` and `wrap` are the two answers to "this value is longer than its
 * column". They are mutually exclusive: `truncate` keeps the row one line tall
 * and ends it with an ellipsis; `wrap` lets the row grow so the whole value
 * stays readable. Without either, the cell's `white-space: nowrap` lets the
 * text run out of its column and over whatever the next column holds — an
 * action control included, which is how a value came to be painted on top of
 * an edit button. */
function getColumnSizingStyle({ width, truncate = false, wrap = false }) {
  if (truncate) return { width: '100%', maxWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis' };
  /* `keep-all` is the Korean rule: break between words, never inside one.
   * `overflow-wrap: anywhere` is the escape hatch for an unbroken token
   * (a URL, an identifier) that is wider than the column on its own. */
  if (wrap) return { width, whiteSpace: 'normal', wordBreak: 'keep-all', overflowWrap: 'anywhere' };
  return { width };
}

/* `columnLabelsHidden` keeps `<th scope="col">` for assistive technology while
 * removing the visible header band. A property table ("항목 | 값") states its
 * columns in the data itself, so the visible band repeats what every row
 * already shows and costs a 44px row of chrome.
 *
 * The label — not the cell — is what gets hidden. An absolutely positioned
 * `<th>` blockifies out of the table box (CSS 2.1 §9.7), and under
 * `table-layout: fixed` the header row is the ONLY row that sets column
 * widths, so hiding the cell itself silently collapses every declared width to
 * an even split. The cell therefore keeps its own layout and loses only its
 * band: zero padding, zero height, no rule. */
const hiddenHeaderCellStyle = (align, sizing) => ({
  ...sizing,
  padding: 0,
  height: 0,
  lineHeight: 0,
  fontSize: 0,
  border: 0,
  borderBottom: 0,
  textAlign: align,
});

const HIDDEN_HEADER_LABEL_STYLE = {
  position: 'absolute',
  width: 1,
  height: 1,
  padding: 0,
  margin: -1,
  overflow: 'hidden',
  clipPath: 'inset(50%)',
  whiteSpace: 'nowrap',
  border: 0,
};

function getTableRowMinHeight(size = 'md') {
  return size === 'sm'
    ? 'var(--lk-table-row-min-height-sm, var(--component-table-row-min-height-sm, 44px))'
    : 'var(--lk-table-row-min-height-md, var(--component-table-row-min-height-md, 52px))';
}

function getTableCellPadding(size = 'md') {
  return size === 'sm'
    ? 'var(--lk-table-cell-pad-sm, var(--component-table-cell-padding-sm, 6px 12px))'
    : 'var(--lk-table-cell-pad-md, var(--component-table-cell-padding-md, 8px 16px))';
}

/** Public style helpers for product-owned native tables that must match LDS Table cells. */
export function getTableHeaderCellStyle({ size = 'md', padding, align = 'left', width, truncate = false, wrap = false } = {}) {
  return { ...thStyle(padding ?? getTableCellPadding(size), getTableRowMinHeight(size)), textAlign: align, ...getColumnSizingStyle({ width, truncate, wrap }) };
}

export function getTableDataCellStyle({ size = 'md', padding, align = 'left', width, truncate = false, wrap = false } = {}) {
  return { ...tdStyle(padding ?? getTableCellPadding(size), getTableRowMinHeight(size)), textAlign: align, ...getColumnSizingStyle({ width, truncate, wrap }) };
}

function TableCellContent({ truncate, children }) {
  if (!truncate) return children;
  return (
    <span
      data-slot="truncated-content"
      style={{ display: 'block', minWidth: 0, maxWidth: '100%', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
    >
      {children}
    </span>
  );
}

function TableRow({ columns, row, rowIndex, size, pad, hover, banded, rowHeaderKey, getRowProps }) {
  const [h, setH] = React.useState(false);
  const rowProps = getRowProps?.(row, rowIndex) ?? {};
  const {
    className,
    style,
    onMouseEnter,
    onMouseLeave,
    ...restRowProps
  } = rowProps;
  // Banded rows already sit on the quietest fill, so their hover wash steps
  // one fill up — the wash must stay visible on top of the band.
  const restBackground = banded ? 'var(--color-semantic-fill-alternative)' : 'transparent';
  const hoverBackground = banded ? 'var(--color-semantic-fill-normal)' : 'var(--color-semantic-fill-alternative)';
  return (
    <tr
      {...restRowProps}
      className={className}
      data-banded={banded || undefined}
      onMouseEnter={(event) => { setH(true); onMouseEnter?.(event); }}
      onMouseLeave={(event) => { setH(false); onMouseLeave?.(event); }}
      style={{ background: hover && h ? hoverBackground : restBackground, transition: 'background var(--dur-fast) var(--ease-out)', ...style }}
    >
      {columns.map((c) => {
        const content = typeof c.render === 'function' ? c.render(row) : row[c.key];
        const cellStyle = getTableDataCellStyle({ size, padding: pad, align: c.align || 'left', width: c.width, truncate: c.truncate, wrap: c.wrap });
        const cellContent = <TableCellContent truncate={c.truncate}>{content}</TableCellContent>;
        // WCAG 1.3.1 / APG Table pattern: the cell that identifies the row is a
        // row header, so a screen reader can read it back with every other cell
        // of that row. Presentation stays identical to a data cell (the <th>
        // user-agent bold is reset) — only the semantics change.
        if (rowHeaderKey != null && c.key === rowHeaderKey) {
          return <th key={c.key} scope="row" style={{ ...cellStyle, fontWeight: 'inherit' }}>{cellContent}</th>;
        }
        return <td key={c.key} style={cellStyle}>{cellContent}</td>;
      })}
    </tr>
  );
}

/**
 * LK ROBOTICS — Table
 * A calm data table: uppercase caption headers on a hairline, tabular rows with
 * a soft hover wash. `columns` describe each field; `render` a cell for custom
 * content (status dots, links). Scrolls horizontally on overflow.
 *
 * Accessibility — column headers carry `scope="col"` and `rowHeaderKey` promotes
 * the identifying cell of each row to `<th scope="row">`, so header/data
 * association survives linearised reading (WCAG 1.3.1, APG Table pattern). The
 * table itself is named by a visible `<caption>`, or by `tableLabel` /
 * `tableLabelledBy` when the title already lives outside the table.
 *
 * `banded` lays every data row on the quietest fill. Use it when a wide table
 * puts real distance between the row's label and its measures — a hairline
 * alone cannot carry the eye across that gutter (Carbon's zebra rationale;
 * grammar pressure-tested on the slide medium, see
 * docs/TABLE_MEDIUM_CONTRACT_PROPOSAL.md). All rows band, never alternate:
 * with few rows a stripe reads as emphasis, and emphasis belongs to status
 * treatments, not geometry.
 *
 * `groupKey` names the field that groups rows. Each CONTIGUOUS run of rows
 * sharing a value opens with a `<th scope="colgroup">` spanning the table —
 * the caller's row order is the report's order, so a value that reappears
 * later opens a second run rather than being silently gathered (reordering
 * rows would rewrite a claim the caller made). The group row carries no band:
 * the bands say "data row", and a label is not one.
 */
export function Table({
  columns = [],
  rows = [],
  size = 'md',
  hover = true,
  banded = false,
  columnLabelsHidden = false,
  caption,
  tableLabel,
  tableLabelledBy,
  rowHeaderKey,
  groupKey,
  getRowId,
  getRowProps,
  className,
  style,
  ...rest
}) {
  // Fallbacks are the former literals — the product medium is byte-identical,
  // a medium that reads farther away re-points the hook (see table-cell-styles).
  const pad = getTableCellPadding(size);
  // A visible <caption> already names the table. An aria-label on top of it
  // would silently replace that visible name and risk a name/visible-text
  // mismatch (WCAG 2.5.3), so the ARIA names only apply without a caption.
  const nameFromAria = caption == null;

  /* The surface scrolls horizontally when the columns outrun their container.
   * WCAG 2.1.1 / `scrollable-region-focusable`: whatever a pointer can scroll,
   * a keyboard must be able to scroll too. This surface used to be a plain
   * `div`, so the columns past the fold were reachable with a mouse and with
   * nothing else — the same contract `ScrollArea` already documents and
   * implements, bypassed by the component that needs it most.
   *
   * Overflow is measured, so a table that fits adds no tab stop. The region
   * borrows the table's own name: it is the same object, and a second name
   * would make a screen reader announce two things where there is one.
   *
   * A caller that already declares the region (a specimen that knows it is
   * always wide) keeps its own `role`/`tabIndex`/name — measurement only fills
   * in what was not stated. */
  const surfaceRef = React.useRef(null);
  const captionId = `${React.useId()}-caption`;
  const [scrolls, setScrolls] = React.useState(false);
  /* The same measurement `ScrollArea` makes, kept here rather than shared:
   * `Table` ships in Product and the layer contract forbids reaching into a
   * Core internal by subpath, and `ScrollArea` itself cannot be reused because
   * it owns `maxHeight` and scrolls both axes while this surface scrolls
   * horizontally and lets the page own its height. Only the x axis counts — a
   * long table must not claim a horizontal region it does not have. */
  React.useEffect(() => {
    const node = surfaceRef.current;
    if (!node) return undefined;
    const measure = () => {
      const next = node.scrollWidth - node.clientWidth > 1;
      setScrolls((prev) => (prev === next ? prev : next));
    };
    measure();
    if (typeof ResizeObserver === 'undefined') return undefined;
    const ro = new ResizeObserver(measure);
    ro.observe(node);
    for (const child of Array.from(node.children)) ro.observe(child);
    return () => ro.disconnect();
  }, [columns, rows, size]);
  const surfaceName = tableLabel ?? rest['aria-label'];
  const surfaceNamedBy = tableLabelledBy ?? rest['aria-labelledby'] ?? (caption != null ? captionId : undefined);
  const surfaceNamed = surfaceName != null || surfaceNamedBy != null;

  return (
    <div
      {...rest}
      ref={surfaceRef}
      className={['lk-scroll-surface', className].filter(Boolean).join(' ')}
      data-scrollbar="auto"
      data-scroll-gutter="auto"
      role={rest.role ?? (scrolls && surfaceNamed ? 'region' : undefined)}
      aria-label={rest['aria-label'] ?? (scrolls && surfaceName != null ? surfaceName : undefined)}
      aria-labelledby={rest['aria-labelledby'] ?? (scrolls && surfaceName == null ? surfaceNamedBy : undefined)}
      tabIndex={rest.tabIndex ?? (scrolls ? 0 : undefined)}
      style={{ overflowX: 'auto', scrollbarGutter: 'auto', ...style }}
    >
      <table
        aria-label={nameFromAria ? tableLabel : undefined}
        aria-labelledby={nameFromAria ? tableLabelledBy : undefined}
        style={{ width: '100%', borderCollapse: 'collapse', fontFamily: 'var(--font-sans)' }}
      >
        {caption != null && (
          <caption
            id={captionId}
            style={{
              captionSide: 'top',
              paddingBottom: 'var(--space-2)',
              color: 'var(--color-semantic-label-strong)',
              fontSize: 'var(--label1-size)',
              lineHeight: 'var(--label1-line)',
              fontWeight: 'var(--fw-semibold)',
              textAlign: 'left',
            }}
          >
            {caption}
          </caption>
        )}
        <thead data-column-labels={columnLabelsHidden ? 'hidden' : undefined}>
          <tr>
            {columns.map((c) => (
              <th
                key={c.key}
                scope="col"
                style={columnLabelsHidden
                  ? hiddenHeaderCellStyle(c.align || 'left', getColumnSizingStyle({ width: c.width, truncate: c.truncate, wrap: c.wrap }))
                  : getTableHeaderCellStyle({ size, padding: pad, align: c.align || 'left', width: c.width, truncate: c.truncate, wrap: c.wrap })}
              >
                {columnLabelsHidden
                  ? <span style={HIDDEN_HEADER_LABEL_STYLE}>{c.label}</span>
                  : <TableCellContent truncate={c.truncate}>{c.label}</TableCellContent>}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((r, ri) => {
            const group = groupKey == null ? undefined : r?.[groupKey];
            const opensGroup = group != null && group !== (groupKey == null ? undefined : rows[ri - 1]?.[groupKey]);
            const row = (
              <TableRow
                key={getRowId ? getRowId(r, ri) : (r?.id ?? ri)}
                columns={columns}
                row={r}
                rowIndex={ri}
                size={size}
                pad={pad}
                hover={hover}
                banded={banded}
                rowHeaderKey={rowHeaderKey}
                getRowProps={getRowProps}
              />
            );
            if (!opensGroup) return row;
            return (
              <React.Fragment key={`group-${group}-${ri}`}>
                <tr data-table-group>
                  <th scope="colgroup" colSpan={columns.length} style={groupThStyle(pad)}>{group}</th>
                </tr>
                {row}
              </React.Fragment>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
